CREATE TABLE auth_projects (id uuid PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE auth_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES auth_projects(id), email text NOT NULL, phone text, full_name text NOT NULL, password_hash text NOT NULL, status text NOT NULL DEFAULT 'pending_email', email_verified boolean NOT NULL DEFAULT false, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE auth_refresh_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES auth_users(id), token_hash text NOT NULL, expires_at timestamp NOT NULL, revoked_at timestamp, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE auth_verification_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES auth_users(id), token_hash text NOT NULL, expires_at timestamp NOT NULL, used_at timestamp, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE auth_password_reset_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES auth_users(id), token_hash text NOT NULL, expires_at timestamp NOT NULL, used_at timestamp, created_at timestamp NOT NULL DEFAULT now());
